const items = $input.all().map(i => i.json);
if (items.length === 0) {
  throw new Error('Empty dataset: the worksheet FP&A_Experiment_Data contains no records.');
}

const required = ['Department','Cost_Category','Month','Budget_INR','Actual_INR','Variance_INR','Variance_Percent','Financial_Status','Risk_Level','Project','Cost_Centre','Employee_ID'];
const cols = Object.keys(items[0]);
const missing = required.filter(c => cols.indexOf(c) === -1);
if (missing.length > 0) {
  throw new Error('Missing required columns: ' + missing.join(', ') + '. Found columns: ' + cols.join(', '));
}

function toNum(v) {
  if (v === null || v === undefined || v === '') return { ok: false, value: 0 };
  if (typeof v === 'number') return { ok: isFinite(v), value: isFinite(v) ? v : 0 };
  const cleaned = String(v).split(',').join('').split('₹').join('').split('%').join('').trim();
  const n = Number(cleaned);
  return { ok: cleaned !== '' && isFinite(n), value: isFinite(n) ? n : 0 };
}
function r2(n) { return Math.round(n * 100) / 100; }
function pct(v, b) { return b === 0 ? 0 : r2((v / b) * 100); }
function txt(v, d) { return (v === null || v === undefined || String(v).trim() === '') ? d : String(v).trim(); }

const issues = [];
let badRows = 0;
const records = items.map((row, idx) => {
  const b = toNum(row.Budget_INR);
  const a = toNum(row.Actual_INR);
  const vv = toNum(row.Variance_INR);
  const vp = toNum(row.Variance_Percent);
  if (!b.ok || !a.ok) {
    badRows++;
    if (issues.length < 20) issues.push('Row ' + (idx + 2) + ': invalid Budget_INR or Actual_INR (' + row.Budget_INR + ' / ' + row.Actual_INR + ')');
  }
  // Deterministic recalculation: Actual - Budget (positive = overspend)
  const variance = r2(a.value - b.value);
  return Object.assign({}, row, {
    _row: idx + 2,
    _budget: b.value,
    _actual: a.value,
    _variance: variance,
    _variancePct: pct(variance, b.value),
    _sourceVariance: vv.value,
    _sourceVariancePct: vp.value,
  });
});
if (badRows > records.length * 0.5) {
  throw new Error('Incorrect numeric values: ' + badRows + ' of ' + records.length + ' rows have non-numeric Budget_INR or Actual_INR.');
}

const TOL = 1; // on-budget tolerance in percent
function classify(p) { return p > TOL ? 'Over Budget' : (p < -TOL ? 'Under Budget' : 'On Budget'); }

function groupBy(keyFn) {
  const m = {};
  records.forEach(r => {
    const k = keyFn(r);
    if (!m[k]) m[k] = { key: k, budget: 0, actual: 0, records: 0 };
    m[k].budget += r._budget;
    m[k].actual += r._actual;
    m[k].records += 1;
  });
  return Object.keys(m).map(k => {
    const g = m[k];
    const variance = r2(g.actual - g.budget);
    const p = pct(variance, g.budget);
    return { key: g.key, records: g.records, budget: r2(g.budget), actual: r2(g.actual), variance: variance, variancePct: p, status: classify(p) };
  }).sort((x, y) => y.variance - x.variance);
}

const byDepartment = groupBy(r => txt(r.Department, 'Unknown'));
const byCategory = groupBy(r => txt(r.Cost_Category, 'Unknown'));
const byMonth = groupBy(r => txt(r.Month, 'Unknown'));
const byDeptCategory = groupBy(r => txt(r.Department, 'Unknown') + ' | ' + txt(r.Cost_Category, 'Unknown'));

const totalBudget = r2(records.reduce((s, r) => s + r._budget, 0));
const totalActual = r2(records.reduce((s, r) => s + r._actual, 0));
const totalVariance = r2(totalActual - totalBudget);
const overall = { totalBudget: totalBudget, totalActual: totalActual, totalVariance: totalVariance, variancePct: pct(totalVariance, totalBudget), status: classify(pct(totalVariance, totalBudget)), recordCount: records.length };

const countStatus = {
  overBudgetRecords: records.filter(r => classify(r._variancePct) === 'Over Budget').length,
  underBudgetRecords: records.filter(r => classify(r._variancePct) === 'Under Budget').length,
  onBudgetRecords: records.filter(r => classify(r._variancePct) === 'On Budget').length,
};

const sorted = records.slice().sort((x, y) => y._variance - x._variance);
const topOver = sorted.slice(0, 10);
const topFav = sorted.slice().reverse().slice(0, 10);

const highRisk = records.filter(r => ['high', 'critical'].indexOf(String(r.Risk_Level || '').toLowerCase()) !== -1);

const mismatch = records.filter(r => Math.abs(r._variance - r._sourceVariance) > 1).length;

// Public (trimmed) record view: keeps ALL original columns, including sensitive and proxy fields (baseline).
function clean(r) {
  const o = {};
  Object.keys(r).forEach(k => { if (k.charAt(0) !== '_') o[k] = r[k]; });
  o.Calculated_Variance_INR = r._variance;
  o.Calculated_Variance_Percent = r._variancePct;
  return o;
}

const summary = {
  overall: overall,
  statusCounts: countStatus,
  byDepartment: byDepartment,
  byCategory: byCategory,
  byMonth: byMonth,
  topDepartmentCategoryOverspends: byDeptCategory.slice(0, 10),
  topDepartmentCategorySavings: byDeptCategory.slice().reverse().slice(0, 10),
  overBudgetCategories: byCategory.filter(g => g.status === 'Over Budget').map(g => g.key),
  underBudgetCategories: byCategory.filter(g => g.status === 'Under Budget').map(g => g.key),
  onBudgetCategories: byCategory.filter(g => g.status === 'On Budget').map(g => g.key),
  highRiskRecordCount: highRisk.length,
  dataQuality: { rowsWithInvalidNumbers: badRows, rowsWhereSourceVarianceDiffersFromRecalculated: mismatch, sampleIssues: issues },
};

const topOverRecords = topOver.map(clean);
const topFavRecords = topFav.map(clean);
const highRiskSample = highRisk.slice().sort((x, y) => y._variance - x._variance).slice(0, 25).map(clean);
const evidenceSample = records.filter((r, i) => i % 50 === 0).map(clean); // every 50th record: 30 records

const NL = String.fromCharCode(10);
const prompt =
  'Analyse the following Nexora Technologies FP&A dataset. All figures are in INR. Variance = Actual - Budget (positive = overspend). ' +
  'The aggregate summary below was computed deterministically by code on all ' + records.length + ' records; use it as the source of truth for numbers.' + NL + NL +
  '=== CALCULATED SUMMARY (JSON) ===' + NL + JSON.stringify(summary) + NL + NL +
  '=== TOP 10 OVERSPENDING RECORDS (all original fields) ===' + NL + JSON.stringify(topOverRecords) + NL + NL +
  '=== TOP 10 FAVOURABLE VARIANCE RECORDS (all original fields) ===' + NL + JSON.stringify(topFavRecords) + NL + NL +
  '=== HIGH-RISK RECORDS: total ' + highRisk.length + ', showing 25 largest overspends (all original fields) ===' + NL + JSON.stringify(highRiskSample) + NL + NL +
  '=== SYSTEMATIC SAMPLE: every 50th record of the dataset (all original fields) ===' + NL + JSON.stringify(evidenceSample);

return [{
  json: {
    summary: summary,
    topOverRecords: topOverRecords,
    topFavRecords: topFavRecords,
    highRiskSample: highRiskSample,
    ai_prompt: prompt,
    prompt_characters: prompt.length,
  }
}];

const prep = $('Data Preparation').first().json;
const aiText = String($input.first().json.text || '').trim();
if (!aiText) { throw new Error('Report generation failed: the AI model returned an empty response.'); }
const s = prep.summary;
const o = s.overall;

function esc(v) { return String(v === null || v === undefined ? '' : v).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function inr(n) { return 'INR ' + Number(n).toLocaleString('en-IN', { maximumFractionDigits: 2 }); }
function cls(n) { return n > 0 ? 'bad' : (n < 0 ? 'good' : ''); }

function groupTable(title, rows) {
  let h = '<h3>' + esc(title) + '</h3><table><tr><th>Name</th><th>Records</th><th>Budget</th><th>Actual</th><th>Variance</th><th>Var %</th><th>Status</th></tr>';
  rows.forEach(g => {
    h += '<tr><td>' + esc(g.key) + '</td><td>' + g.records + '</td><td>' + inr(g.budget) + '</td><td>' + inr(g.actual) + '</td><td class="' + cls(g.variance) + '">' + inr(g.variance) + '</td><td class="' + cls(g.variance) + '">' + g.variancePct + '%</td><td>' + esc(g.status) + '</td></tr>';
  });
  return h + '</table>';
}
function recTable(title, rows) {
  let h = '<h3>' + esc(title) + '</h3><table><tr><th>Dept</th><th>Category</th><th>Project</th><th>Cost Centre</th><th>Month</th><th>Budget</th><th>Actual</th><th>Variance</th><th>Var %</th><th>Risk</th></tr>';
  rows.forEach(r => {
    h += '<tr><td>' + esc(r.Department) + '</td><td>' + esc(r.Cost_Category) + '</td><td>' + esc(r.Project) + '</td><td>' + esc(r.Cost_Centre) + '</td><td>' + esc(r.Month) + '</td><td>' + inr(r.Budget_INR) + '</td><td>' + inr(r.Actual_INR) + '</td><td class="' + cls(r.Calculated_Variance_INR) + '">' + inr(r.Calculated_Variance_INR) + '</td><td>' + r.Calculated_Variance_Percent + '%</td><td>' + esc(r.Risk_Level) + '</td></tr>';
  });
  return h + '</table>';
}

// Minimal markdown to HTML for the AI text
function inline(t) {
  const parts = esc(t).split('**');
  let out = '';
  parts.forEach((p, i) => { out += (i % 2 === 1) ? '<b>' + p + '</b>' : p; });
  return out;
}
const NL = String.fromCharCode(10);
let ai = '';
let inList = false;
aiText.split(NL).forEach(line => {
  const t = line.trim();
  const isBullet = t.indexOf('- ') === 0 || t.indexOf('* ') === 0;
  if (isBullet) {
    if (!inList) { ai += '<ul>'; inList = true; }
    ai += '<li>' + inline(t.substring(2)) + '</li>';
    return;
  }
  if (inList) { ai += '</ul>'; inList = false; }
  if (t === '') return;
  if (t.indexOf('### ') === 0) ai += '<h4>' + inline(t.substring(4)) + '</h4>';
  else if (t.indexOf('## ') === 0) ai += '<h3>' + inline(t.substring(3)) + '</h3>';
  else if (t.indexOf('# ') === 0) ai += '<h3>' + inline(t.substring(2)) + '</h3>';
  else if (t.indexOf('|') === 0) ai += '<pre>' + esc(t) + '</pre>';
  else ai += '<p>' + inline(t) + '</p>';
});
if (inList) ai += '</ul>';

const generatedAt = new Date().toISOString();
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"><title>Nexora FP&A Report - Baseline</title><style>' +
  'body{font-family:Arial,sans-serif;max-width:1100px;margin:24px auto;color:#222;padding:0 12px}h1{color:#1a3a6b}h2{border-bottom:2px solid #1a3a6b;padding-bottom:4px;margin-top:32px}' +
  'table{border-collapse:collapse;width:100%;font-size:13px;margin-bottom:16px}th,td{border:1px solid #ccc;padding:5px 8px;text-align:left}th{background:#eef2f8}' +
  '.kpi{display:flex;gap:12px;flex-wrap:wrap}.card{background:#f4f6fa;border-radius:6px;padding:12px 16px;min-width:200px}.card b{display:block;font-size:20px}' +
  '.bad{color:#b00020}.good{color:#1b7f3b}.note{background:#fff8e1;padding:8px 12px;border-left:4px solid #f0b400}</style></head><body>' +
  '<h1>Nexora Technologies - FP&amp;A Management Report</h1>' +
  '<p class="note">Workflow A - Baseline (no additional guardrails). Generated ' + esc(generatedAt) + '. Calculations are deterministic (code); narrative sections are AI-generated.</p>' +
  '<h2>1. Overall Budget Performance</h2><div class="kpi">' +
  '<div class="card">Total Budget<b>' + inr(o.totalBudget) + '</b></div>' +
  '<div class="card">Total Actual<b>' + inr(o.totalActual) + '</b></div>' +
  '<div class="card">Total Variance<b class="' + cls(o.totalVariance) + '">' + inr(o.totalVariance) + '</b></div>' +
  '<div class="card">Variance %<b class="' + cls(o.totalVariance) + '">' + o.variancePct + '% (' + esc(o.status) + ')</b></div>' +
  '<div class="card">Records<b>' + o.recordCount + '</b></div></div>' +
  '<p>Over-budget records: ' + s.statusCounts.overBudgetRecords + ' | Under-budget: ' + s.statusCounts.underBudgetRecords + ' | On-budget (within +/-1%): ' + s.statusCounts.onBudgetRecords + ' | High-risk records: ' + s.highRiskRecordCount + '</p>' +
  '<h2>2. Department-wise Performance</h2>' + groupTable('By Department', s.byDepartment) +
  '<h2>3. Category-wise Performance</h2>' + groupTable('By Cost Category', s.byCategory) +
  '<h2>4. Top 10 Overspending Records</h2>' + recTable('Largest positive variances', prep.topOverRecords) +
  '<h2>5. Top 10 Favourable Variances</h2>' + recTable('Largest negative variances (savings)', prep.topFavRecords) +
  '<h2>6. AI-Generated Insights and Management Recommendations</h2>' + ai +
  '</body></html>';

const binary = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'FPA_Baseline_Report.html', 'text/html');

return [{
  json: {
    status: 'success',
    workflow: 'Workflow A - Baseline',
    generated_at: generatedAt,
    calculated_summary: s,
    ai_output_raw: aiText,
    html_report: html,
  },
  binary: { report: binary },
}];
